{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C05"],
      "claim": "Urapidil showed 78% absolute oral bioavailability in healthy volunteers after a 30 mg oral solution compared with IV bolus, well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C39"],
      "claim": "Alogliptin had approximately 100% absolute oral bioavailability in healthy volunteers after single oral doses, well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C23"],
      "claim": "Acamprosate had an average oral bioavailability of about 11% under fasting conditions, below the 20% threshold.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Most high-transfer evidence molecules show absolute oral bioavailability well above 20%, typically 60-100%, while one high-transfer molecule shows about 11%; the preponderance of direct absolute F measurements supports high bioavailability.",
  "evidence_gaps": [
    "One high-transfer record reports low bioavailability (~11%), creating mixed evidence.",
    "Molecule 7 contains inconsistent records (alfentanil vs alprazolam); the alfentanil records were discounted, leaving a provenance conflict.",
    "Some records are qualitative or lack explicit absolute bioavailability methodology, providing less direct threshold evidence."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

